import ghidra.app.script.GhidraScript; import ghidra.program.model.listing.*; import ghidra.program.model.address.*; import java.io.*;
public class VerifyAsm extends GhidraScript { public void run() throws Exception { String out=getScriptArgs()[0]; try(PrintWriter pw=new PrintWriter(out)){ for(long[] r: new long[][]{{0x13d160,0x13d178},{0x144e44,0x144e5c},{0x3d6d58,0x3d6e08},{0x3d6e08,0x3d6e28},{0x3d6e28,0x3d6e48},{0x3d6eb0,0x3d6f50},{0x3d6f50,0x3d6f84},{0x144e6c,0x144e78},{0x3d6fa8,0x3d6fd8},{0x1f10c8,0x1f10d4},{0x174ba0,0x174ba8},{0x1751ac,0x1751b8},{0x1ad928,0x1ad934},{0x1ad9c4,0x1ad9d0},{0x3d6fe8,0x3d7044},{0x3d7044,0x3d7104},{0x3d7104,0x3d7148},{0x3d7148,0x3d716c},{0x3d716c,0x3d7190},{0x3d7190,0x3d71b4}}){ Address a=toAddr(r[0]); clearListing(a,toAddr(r[1])); disassemble(a); while(a.getOffset()<r[1]){ Instruction in=getInstructionAt(a); pw.printf("%s %s\n",a,in); a=a.add(in!=null?in.getLength():4);} pw.println(); } } } }
